input.command:
cat > utils/request.ts <<'EOF'
/**
 * Clone a request without ever throwing. If `clone()` fails (e.g. the body is
 * disturbed or locked), a bodyless copy carrying the same metadata is returned.
 */
export function safeCloneRequest(request?: Request): Request | undefined {
	if (!request) {
		return undefined;
	}
	try {
		return request.clone();
	} catch {
		const init: RequestInit = {
			method: request.method,
			headers: new Headers(request.headers),
		};
		const optional = [
			"cache",
			"credentials",
			"integrity",
			"keepalive",
			"mode",
			"redirect",
			"referrer",
			"referrerPolicy",
			"signal",
		] as const;
		for (const key of optional) {
			try {
				const value = request[key];
				if (value !== undefined) {
					(init as Record<string, unknown>)[key] = value;
				}
			} catch {}
		}
		try {
			return new Request(request.url, init);
		} catch {
			// Some options may be rejected by the runtime; retry with the essentials.
			return new Request(request.url, {
				method: request.method,
				headers: new Headers(request.headers),
			});
		}
	}
}
EOF
for f in api/routes/sign-in.ts api/routes/sign-up.ts api/routes/email-verification.ts; do
sed -i 's/ctx\.request?\.clone()/safeCloneRequest(ctx.request)/' $f
sed -i '0,/^import /s//import { safeCloneRequest } from "..\/..\/utils\/request";\nimport /' $f
done
grep -rn "safeCloneRequest" api | head -20; cd .. && npx tsc --noEmit -p . 2>&1 | head

